<script setup>
import {onMounted,ref,nextTick} from 'vue';
const props=defineProps({eventId:Number});const result=ref(null),error=ref(''),busy=ref(false),canvas=ref(null);let drawing=false,distance=0,last=null;
const base=()=>'/api/student/events/'+props.eventId+'/gift';
function fail(e){error.value=e.response?.data?.message||'Não foi possível abrir seu presente. Tente novamente.';}
async function reveal(){if(busy.value)return;busy.value=true;error.value='';try{result.value=(await window.axios.post(base())).data;}catch(e){fail(e);}finally{busy.value=false;}}
function down(e){drawing=true;last=[e.offsetX,e.offsetY];e.target.setPointerCapture(e.pointerId);}
function move(e){if(!drawing||busy.value)return;const point=[e.offsetX,e.offsetY],ctx=canvas.value.getContext('2d');ctx.globalCompositeOperation='destination-out';ctx.lineWidth=36;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(...last);ctx.lineTo(...point);ctx.stroke();distance+=Math.hypot(point[0]-last[0],point[1]-last[1]);last=point;if(distance>350){drawing=false;reveal();}}
onMounted(async()=>{try{const data=(await window.axios.get(base())).data;if(data.gift)result.value=data;}catch(e){fail(e);}await nextTick();if(canvas.value){const c=canvas.value,ctx=c.getContext('2d');c.width=c.clientWidth;c.height=164;ctx.fillStyle='#151715';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='#a3e635';ctx.textAlign='center';ctx.font='bold 20px sans-serif';ctx.fillText('Raspe para descobrir',c.width/2,88);}});
</script>
<template><section class="student-card gift-card"><p class="student-overline">MEU PRESENTE</p><h2>Um cuidado para você</h2><p v-if="error" role="alert">{{error}}</p><template v-if="result?.gift"><h3>{{result.gift.name}}</h3><p>{{result.gift.message}}</p><p>{{result.gift.instructions}}</p><strong v-if="result.deliveredAt">✓ Retirada confirmada pela equipe</strong><p v-else>Mostre este resultado à equipe para retirar.</p></template><template v-else><canvas ref="canvas" aria-label="Área para raspar e revelar seu presente" @pointerdown="down" @pointermove="move" @pointerup="drawing=false" @pointercancel="drawing=false" /><button class="btn-primary" :disabled="busy" @click="reveal">{{busy?'Revelando…':'Revelar meu presente'}}</button></template></section></template>
<style scoped>.gift-card{padding:24px!important;margin-top:20px}.gift-card h2{font-size:24px;font-weight:750;margin:12px 0}.gift-card h3{font-size:28px;font-weight:800;margin:20px 0}.gift-card p{line-height:1.7;margin:12px 0;white-space:pre-line;overflow-wrap:anywhere}.gift-card canvas{width:100%;height:164px;border-radius:16px;touch-action:none;margin:16px 0}.gift-card button{min-height:44px;white-space:normal}</style>
